insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0003-0000-4000-8000-000000000011', 'en', null, 'Supply Chain & Operations', 'A practical first course in how goods, information, and money move from raw material to customer — forecasting, inventory, logistics, and continuous improvement. Built from openly-licensed OER Commons material (Operations & Supply Chain, CC BY).', null, 'work', 17, true, 'business', '{bbbb0003-0000-4000-8000-000000000001}')
