insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0003-0000-4000-8000-000000000011', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"A supply chain moves three things end-to-end. Which set is correct?","options":["goods, information, money","goods, workers, factories","money, taxes, contracts","orders, emails, meetings"],"answer":0,"explanation":"Goods flow downstream to the customer, money flows upstream, and information flows both ways — see ''What a supply chain is''."},{"prompt":"Demand forecasting is mainly used to…","options":["set the tax rate","plan how much to make or buy before demand arrives","hire the CEO","design the logo"],"answer":1,"explanation":"Forecasts drive production and purchasing decisions ahead of actual demand — see ''Demand forecasting''."},{"prompt":"The Economic Order Quantity (EOQ) balances…","options":["price and quality","ordering cost against holding cost","wages against rent","supply against demand exactly"],"answer":1,"explanation":"EOQ finds the order size that minimizes the sum of ordering and holding cost — see ''Inventory management''."},{"prompt":"Safety stock exists to protect against…","options":["theft only","variability in demand and lead time","high prices","slow computers"],"answer":1,"explanation":"Safety stock buffers uncertainty so you don''t stock out during the lead time — see ''Inventory management''."},{"prompt":"''Just-in-Time'' (JIT) inventory aims to…","options":["hold as much stock as possible","receive material only as it is needed","buy once a year","ignore suppliers"],"answer":1,"explanation":"JIT minimizes on-hand inventory by timing deliveries to need — see ''Inventory management''."},{"prompt":"Procurement is the business function that…","options":["ships finished goods to stores","sources and buys goods and services from suppliers","writes the marketing plan","audits the payroll"],"answer":1,"explanation":"Procurement selects suppliers and manages purchasing — see the checkpoints and key terms."},{"prompt":"Logistics is chiefly concerned with…","options":["advertising","transportation, warehousing, and distribution","hiring","product design"],"answer":1,"explanation":"Logistics moves and stores goods across the network — see ''Logistics & distribution''."},{"prompt":"Six Sigma and Lean are approaches to…","options":["raising prices","reducing defects and waste to improve quality","avoiding taxes","expanding the sales team"],"answer":1,"explanation":"Lean removes waste; Six Sigma reduces variation and defects — see ''Quality & continuous improvement''."}]}'::jsonb, null, 10),
  (2, 'What a supply chain is', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe a supply chain as three linked flows and name its main stages. Warm-up: from the diagnostic, which three things move through a supply chain?"},{"heading":"The idea","text":"A *supply chain* is the network that turns raw materials into a product in a customer''s hands. Three flows run through it: *goods* move downstream (supplier → manufacturer → distributor → retailer → customer); *money* moves upstream as each stage pays the one before it; and *information* (orders, forecasts, tracking) moves in both directions. When information is poor, small changes in customer demand get amplified stage by stage into big swings in factory orders — the *bullwhip effect*. Good supply chains share information to keep those swings small."},{"heading":"Worked example","text":"Trace a coffee mug. A clay supplier ships to a factory (supplier lead time 10 days); the factory molds and fires it (manufacturing 5 days); a distribution center receives and sorts it (distribution 3 days); the store shelves it (retail 2 days). End-to-end lead time = 10 + 5 + 3 + 2 = 20 days. That''s how long the chain must ''see ahead'' — you must plan roughly 20 days before a customer wants the mug."},{"heading":"Your turn","text":"(1) A retailer''s order to its distributor is which flow — goods, money, or information? (2) A refund sent back to a customer is which flow? (3) Stages take 8, 6, 4, and 1 days; what is end-to-end lead time? (4) If a tiny rise in store sales makes the factory double its parts order, what is that effect called? Answers: (1) information; (2) money; (3) 8 + 6 + 4 + 1 = 19 days; (4) the bullwhip effect."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking a supply chain is only trucks and warehouses — information flow matters just as much. Mistake: assuming money and goods move the same direction (they move opposite ways). Exit: (a) Which flow moves upstream? (b) Sharing demand information reduces which effect? Answers: money; the bullwhip effect."}]}'::jsonb, 'Goods flow down to the customer; money flows up; information flows both ways.', 12),
  (3, 'Demand forecasting & planning', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Compute a moving-average and an exponential-smoothing forecast and measure forecast error. Warm-up: why must you forecast demand *before* you can plan production?"},{"heading":"The idea","text":"*Forecasting* estimates future demand so you can plan supply. Simple time-series methods use past demand: a *moving average* takes the mean of the last N periods; *exponential smoothing* nudges the old forecast toward the latest actual by a weight α (0–1): new forecast = old forecast + α × (actual − old forecast). A bigger α reacts faster but is noisier. You judge a method by its error — the *mean absolute deviation* (MAD) is the average size of the misses."},{"heading":"Worked example","text":"Sales for three months were 90, 105, 120. A 3-month moving average forecast for next month = (90 + 105 + 120) / 3 = 315 / 3 = 105 units. Now exponential smoothing: last forecast 100, actual 110, α = 0.3 → new forecast = 100 + 0.3 × (110 − 100) = 100 + 3 = 103 units. Measuring error: if three forecasts missed by +5, −3, and +4, then MAD = (|5| + |−3| + |4|) / 3 = 12 / 3 = 4 units on average."},{"heading":"Your turn","text":"(1) Demand was 60, 66, 72; compute the 3-period moving-average forecast. (2) Last forecast 50, actual 60, α = 0.2; compute the exponential-smoothing forecast. (3) Errors were +2, −6, +4; compute MAD. (4) Which reacts faster to a sudden jump, α = 0.1 or α = 0.6? Answers: (1) (60 + 66 + 72)/3 = 198/3 = 66; (2) 50 + 0.2 × (60 − 50) = 50 + 2 = 52; (3) (2 + 6 + 4)/3 = 12/3 = 4; (4) α = 0.6."},{"heading":"Common mistakes & exit ticket","text":"Mistake: expecting a forecast to be exactly right — always plan for error with a buffer. Mistake: using a huge α because it ''follows the data'' — it just chases noise. Exit: (a) In smoothing, what does α weight? (b) What does MAD measure? Answers: the latest actual (the newest error); the average absolute forecast error."}]}'::jsonb, 'A forecast is always wrong; the goal is to be less wrong and to measure the error.', 13),
  (4, 'Inventory management: EOQ, safety stock, JIT', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Compute an Economic Order Quantity, a reorder point, and safety stock, and explain JIT. Warm-up: why does ordering in huge batches cost money even if the goods never spoil?"},{"heading":"The idea","text":"Every order has two opposing costs: *ordering cost* (paperwork, setup, shipping — paid per order) and *holding cost* (storage, capital, obsolescence — paid per unit per year). Big orders mean fewer orders but more stock sitting around; small orders mean the reverse. The *Economic Order Quantity* minimizes their sum: EOQ = √(2DS/H), where D = annual demand, S = cost per order, H = holding cost per unit per year. You reorder when stock hits the *reorder point* = (daily demand × lead time) + *safety stock*, where safety stock = z × σ buffers demand and lead-time variability (z ≈ 1.65 for 95% service). *Just-in-Time* pushes stock toward zero by receiving material exactly as needed — powerful, but it needs reliable suppliers."},{"heading":"Worked example","text":"Annual demand D = 10,000 units, ordering cost S = $40, holding cost H = $5/unit/year. EOQ = √(2 × 10,000 × 40 / 5) = √(800,000 / 5) = √160,000 = 400 units. Orders per year = 10,000 / 400 = 25. Reorder point: with 250 working days, daily demand = 10,000 / 250 = 40 units/day; lead time 4 days → demand during lead time = 40 × 4 = 160 units. Safety stock for σ = 20 at 95% service = 1.65 × 20 = 33 units. Reorder point = 160 + 33 = 193 units: when stock falls to 193, place an order for 400."},{"heading":"Your turn","text":"(1) D = 4,000, S = $20, H = $4; compute EOQ. (2) With that EOQ, how many orders per year? (3) Daily demand 50, lead time 3 days, no safety stock; compute the reorder point. (4) Does JIT raise or lower average inventory? Answers: (1) EOQ = √(2 × 4,000 × 20 / 4) = √(160,000 / 4) = √40,000 = 200 units; (2) 4,000 / 200 = 20 orders; (3) 50 × 3 = 150 units; (4) it lowers average inventory."},{"heading":"Common mistakes & exit ticket","text":"Mistake: putting holding cost H in the numerator of EOQ — it goes in the denominator (higher holding cost → smaller orders). Mistake: forgetting to add safety stock to the reorder point. Exit: (a) In EOQ, if ordering cost S rises, do you order more or less each time? (b) What does safety stock protect against? Answers: more per order (fewer, bigger orders); demand and lead-time variability."}]}'::jsonb, 'EOQ = √(2DS/H). Reorder point = demand during lead time + safety stock.', 14),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"In a supply chain, money generally flows…","options":["downstream to the customer","upstream toward suppliers","in a circle","not at all"],"answer":1,"explanation":"Each stage pays the stage before it, so money moves upstream."},{"prompt":"Exponential smoothing forecast: old forecast 200, actual 220, α = 0.5. The new forecast is…","options":["200","210","220","240"],"answer":1,"explanation":"200 + 0.5 × (220 − 200) = 200 + 10 = 210."},{"prompt":"EOQ with D = 10,000, S = $40, H = $5 equals…","options":["200 units","300 units","400 units","800 units"],"answer":2,"explanation":"√(2 × 10,000 × 40 / 5) = √160,000 = 400."},{"prompt":"Daily demand 40, lead time 4 days, safety stock 33. The reorder point is…","options":["160","173","193","200"],"answer":2,"explanation":"40 × 4 + 33 = 160 + 33 = 193."},{"prompt":"The bullwhip effect describes…","options":["faster shipping","demand swings growing larger upstream","a pricing model","a warehouse layout"],"answer":1,"explanation":"Small demand changes amplify stage by stage up the chain."},{"prompt":"MAD (mean absolute deviation) measures…","options":["total sales","average forecast error size","the reorder point","holding cost"],"answer":1,"explanation":"MAD is the average absolute miss of the forecast."}]}'::jsonb, null, 8),
  (6, 'Logistics & distribution', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Compute landed cost and fill rate, and explain the speed-versus-cost trade-off across transport modes. Warm-up: why might a company ship the same product by both ocean and air?"},{"heading":"The idea","text":"*Logistics* moves and stores goods: transportation, warehousing, and distribution-network design. Transport *modes* trade speed against cost — ocean and rail are cheap but slow; trucking is flexible and mid-cost; air is fast but expensive. *Warehouses* and *distribution centers* (DCs) hold and sort stock closer to customers; more DCs mean faster delivery but higher fixed cost. Two everyday metrics: *landed cost* (the true delivered cost = unit cost + freight + duties) tells you what an item really costs, and *fill rate* (orders filled from stock ÷ orders requested) measures service."},{"heading":"Worked example","text":"A part costs $10 from the supplier. Freight adds $2 per unit, and import duty is 5% of the unit cost = 0.05 × $10 = $0.50. Landed cost = $10 + $2 + $0.50 = $12.50 — 25% more than the sticker price, which is why sourcing decisions use landed cost, not unit price. Service check: a DC received 400 order lines this week and shipped 380 complete from stock. Fill rate = 380 / 400 = 0.95 = 95%."},{"heading":"Your turn","text":"(1) Unit cost $8, freight $1.50, duty 10% of unit cost; compute landed cost. (2) A DC filled 270 of 300 lines; compute the fill rate. (3) You must deliver a spare part overnight to stop a factory line-down — cheap ocean or costly air? (4) True or false: adding distribution centers always lowers total cost. Answers: (1) 8 + 1.50 + 0.10 × 8 = 8 + 1.50 + 0.80 = $10.30; (2) 270 / 300 = 90%; (3) air (speed outweighs cost here); (4) false — it raises fixed cost even as it speeds delivery."},{"heading":"Common mistakes & exit ticket","text":"Mistake: comparing suppliers on unit price alone and ignoring freight and duty. Mistake: assuming faster transport is always worth it — match the mode to the need. Exit: (a) What three parts make up landed cost? (b) What does fill rate measure? Answers: unit cost + freight + duties; the share of orders filled from stock."}]}'::jsonb, 'Landed cost = unit cost + freight + duties. Fill rate = orders filled ÷ orders requested.', 12),
  (7, 'Quality & continuous improvement', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain Lean and Six Sigma and compute a defects-per-million-opportunities (DPMO) and a first-pass yield. Warm-up: is it cheaper to inspect defects out at the end, or to prevent them?"},{"heading":"The idea","text":"*Lean* attacks *waste* — anything the customer wouldn''t pay for. The classic seven wastes are overproduction, waiting, transport, over-processing, excess inventory, motion, and defects. *Six Sigma* attacks *variation* using the DMAIC cycle (Define, Measure, Analyze, Improve, Control) to drive defects toward near-zero — a true ''six sigma'' process allows only 3.4 defects per million opportunities. Both rest on *continuous improvement* (kaizen) and the *PDCA* loop (Plan, Do, Check, Act): small, constant, evidence-based fixes beat rare big overhauls."},{"heading":"Worked example","text":"A line made 1,000 units; each unit has 3 places a defect could occur (3 opportunities), and inspectors found 12 defects. DPMO = defects ÷ (units × opportunities) × 1,000,000 = 12 ÷ (1,000 × 3) × 1,000,000 = 12 ÷ 3,000 × 1,000,000 = 4,000 DPMO — far above the six-sigma target of 3.4. First-pass yield: of 1,000 units, 950 passed with no rework, so yield = 950 / 1,000 = 95%. The 50 reworked units are pure waste in Lean terms."},{"heading":"Your turn","text":"(1) 6 defects, 500 units, 4 opportunities each; compute DPMO. (2) 900 of 1,000 units pass first time; compute first-pass yield. (3) A worker walks 30 m to fetch a tool every cycle — which of the seven wastes is that? (4) What do the letters DMAIC stand for? Answers: (1) 6 ÷ (500 × 4) × 1,000,000 = 6 ÷ 2,000 × 1,000,000 = 3,000 DPMO; (2) 900 / 1,000 = 90%; (3) motion; (4) Define, Measure, Analyze, Improve, Control."},{"heading":"Common mistakes & exit ticket","text":"Mistake: confusing Lean (remove waste) with Six Sigma (reduce variation) — they''re complementary, not the same. Mistake: thinking quality means more inspection; it means preventing defects at the source. Exit: (a) How many defects per million does ''six sigma'' allow? (b) Name the improvement loop with letters P-D-C-A. Answers: 3.4 per million; Plan-Do-Check-Act."}]}'::jsonb, 'Lean removes waste; Six Sigma reduces variation. DMAIC = Define, Measure, Analyze, Improve, Control.', 13),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"lead time","translation":"the time between placing an order and receiving the goods","example":"A 4-day lead time means you must reorder before stock runs out."},{"term":"Economic Order Quantity (EOQ)","translation":"the order size that minimizes total ordering plus holding cost","example":"EOQ = √(2DS/H); with D=10,000, S=$40, H=$5 it is 400 units."},{"term":"safety stock","translation":"extra inventory held to buffer demand and lead-time variability","example":"Safety stock of 33 units keeps service at 95% during the lead time."},{"term":"reorder point","translation":"the stock level that triggers a new order","example":"Reorder point = demand during lead time + safety stock = 160 + 33 = 193."},{"term":"procurement","translation":"the function that sources and buys goods and services from suppliers","example":"Procurement negotiated a lower landed cost with a second supplier."},{"term":"bullwhip effect","translation":"the amplification of demand swings as orders move upstream","example":"Sharing point-of-sale data reduced the bullwhip effect."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"A part costs $10, freight $2, duty 5% of cost. Landed cost is…","options":["$10.50","$12.00","$12.50","$13.00"],"answer":2,"explanation":"10 + 2 + 0.05 × 10 = 10 + 2 + 0.50 = 12.50."},{"prompt":"A DC filled 380 of 400 order lines. Fill rate is…","options":["80%","90%","95%","98%"],"answer":2,"explanation":"380 / 400 = 0.95 = 95%."},{"prompt":"12 defects, 1,000 units, 3 opportunities each. DPMO is…","options":["400","1,200","4,000","12,000"],"answer":2,"explanation":"12 ÷ (1,000 × 3) × 1,000,000 = 4,000."},{"prompt":"Which is one of Lean''s seven wastes?","options":["profit","overproduction","forecasting","procurement"],"answer":1,"explanation":"Overproduction is a classic Lean waste."},{"prompt":"DMAIC stands for Define, Measure, Analyze, Improve, and…","options":["Control","Complete","Cancel","Contract"],"answer":0,"explanation":"The final step is Control — locking in the improvement."},{"prompt":"Procurement is responsible for…","options":["delivering to customers","sourcing and buying from suppliers","forecasting the weather","designing packaging"],"answer":1,"explanation":"Procurement manages sourcing and supplier relationships."}]}'::jsonb, null, 8),
  (10, 'Applied project: map and improve a real supply chain', 'writing', '{"sections":[{"heading":"The task","text":"Pick one everyday product you can actually buy (say, a bag of coffee, a phone case, or a bottle of shampoo). Map its supply chain end-to-end and propose one concrete improvement. You won''t gather private company data — you''ll reason rigorously from what you can observe and estimate."},{"heading":"Milestones","text":"1) Draw the stages from raw material to your hands and label the three flows (goods, money, information). 2) Estimate the lead time of each stage and add them for an end-to-end lead time. 3) Pick one lever from this course — a better forecast, an EOQ or reorder-point change, a transport-mode switch, or a Lean waste to remove — and show the math or logic for why it helps. 4) Name one risk your change creates (e.g. JIT raises stock-out risk if a supplier is unreliable)."},{"heading":"Self-check rubric","text":"✔ All stages are shown and the three flows are labeled correctly (money upstream, goods downstream, information both ways). ✔ End-to-end lead time is the sum of stage lead times. ✔ Your improvement uses a real formula or metric from the course (EOQ, reorder point, landed cost, fill rate, or DPMO) with the numbers shown. ✔ You named a genuine trade-off, not a free lunch. If all four hold, you''ve reasoned like a supply-chain analyst."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0003-0000-4000-8000-000000000011' and l.position = v.pos
);
